SELECT v.title,v.path,v.method,N'GB28181 设备分组',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,1 FROM (VALUES
 (N'创建自定义分组','/api/gb28181/device-mgmt/custom-groups','POST'),(N'修改自定义分组','/api/gb28181/device-mgmt/custom-groups/:id','PATCH'),(N'移动自定义分组','/api/gb28181/device-mgmt/custom-groups/:id/move','POST'),(N'删除自定义分组','/api/gb28181/device-mgmt/custom-groups/:id','DELETE'),(N'添加分组设备','/api/gb28181/device-mgmt/custom-groups/:id/devices','POST'),(N'移除分组设备','/api/gb28181/device-mgmt/custom-groups/:id/devices/remove','POST')) v(title,path,method)
WHERE NOT EXISTS (SELECT 1 FROM [sys_api] a WHERE a.[path]=v.path AND a.[method]=v.method AND a.[deleted_at] IS NULL);
