INSERT INTO [sys_api] ([title],[path],[method],[api_group],[created_at],[updated_at],[created_by])
INSERT INTO [sys_menu] ([parent_id],[path],[name],[title],[type],[permission],[hide],[created_at],[updated_at],[created_by]) SELECT 140355,'','',N'管理自定义分组',3,'gb28181:device-group:manage',1,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,1 WHERE NOT EXISTS (SELECT 1 FROM [sys_menu] WHERE [permission]='gb28181:device-group:manage' AND [deleted_at] IS NULL);
INSERT INTO [sys_role_menu] ([role_id],[menu_id]) SELECT 1,m.[id] FROM [sys_menu] m WHERE m.[permission]='gb28181:device-group:manage' AND NOT EXISTS (SELECT 1 FROM [sys_role_menu] x WHERE x.[role_id]=1 AND x.[menu_id]=m.[id]);
INSERT INTO [sys_menu_api] ([menu_id],[api_id]) SELECT m.[id],a.[id] FROM [sys_menu] m CROSS JOIN [sys_api] a WHERE m.[permission]='gb28181:device-group:manage' AND a.[path] LIKE '/api/gb28181/device-mgmt/custom-groups%' AND NOT EXISTS (SELECT 1 FROM [sys_menu_api] x WHERE x.[menu_id]=m.[id] AND x.[api_id]=a.[id]);
INSERT INTO [sys_casbin_rule] ([ptype],[v0],[v1],[v2],[v3],[v4],[v5]) SELECT 'p','role_1',a.[path],a.[method],'*','','' FROM [sys_api] a WHERE a.[path] LIKE '/api/gb28181/device-mgmt/custom-groups%' AND NOT EXISTS (SELECT 1 FROM [sys_casbin_rule] x WHERE x.[ptype]='p' AND x.[v0]='role_1' AND x.[v1]=a.[path] AND x.[v2]=a.[method] AND x.[v3]='*');
